// Package: AWSSDK.SimpleNotificationation
using Amazon.SimpleNotificationation;
using Amazon.SimpleNotificationation.Model;

var snsClient = new AmazonSimpleNotificationServiceClient(RegionEndpoint.USEast1);
string topicArn = "arn:aws:sns:us-east-1:123456789012:aspnet-order-events";

// Subscribe two SQS queues to the same topic
var analyticsQueueArn = "arn:aws:sqs:us-east-1:123456789012:analytics-queue";
var emailQueueArn = "arn:aws:sqs:us-east-1:123456789012:email-queue";

await snsClient.SubscribeAsync(new SubscribeRequest
{
    TopicArn = topicArn,
    Protocol = "sqs",
    Endpoint = analyticsQueueArn
});

await snsClient.SubscribeAsync(new SubscribeRequest
{
    TopicArn = topicArn,
    Protocol = "sqs",
    Endpoint = emailQueueArn
});

// Each queue receives a copy of the message

using Amazon.SQS;
using Amazon.SQS.Model;

var sqsClient = new AmazonSQSClient(RegionEndpoint.USEast1);
string sourceQueueUrl = "https://sqs.us-east-1.amazonaws.com/123456789012/analytics-queue";
string dlqUrl = "https://sqs.us-east-1.amazonaws.com/123456789012/analytics-dlq";

var redrivePolicy = new RedrivePolicy
{
    deadLetterTargetArn = "arn:aws:sqs:us-east-1:123456789012:analytics-dlq",
    maxReceiveCount = 5
};

await sqsClient.SetQueueAttributesAsync(new SetQueueAttributesRequest
{
    QueueUrl = sourceQueueUrl,
    Attributes = { [QueueAttributeName.RedrivePolicy] = redrivePolicy.ToJson() }
});

Console.WriteLine("DLQ configured for analytics-queue.");
